import{_ as e,o as t,c as r,aA as n}from"./chunks/framework.BMzE2Z9R.js";const m=JSON.parse('{"title":"NARS","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"nars/index.md","filePath":"nars/index.md","lastUpdated":1778399398000}'),o={name:"nars/index.md"};function s(i,a,p,h,l,d){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="nars" tabindex="-1">NARS <a class="header-anchor" href="#nars" aria-label="Permalink to &quot;NARS&quot;">​</a></h1><p><strong>非公理推理系统</strong> (Non-Axiomatic Reasoning System)。</p><p>此项目由美国天普大学 <a href="https://cis.temple.edu/~pwang/" title="王培" target="_blank" rel="noreferrer">王培</a> 教授主导。</p><h2 id="项目目标" tabindex="-1">项目目标 <a class="header-anchor" href="#项目目标" aria-label="Permalink to &quot;项目目标&quot;">​</a></h2><p>试图构建一个通用人工智能系统，这里说的 <strong>通用</strong>，代表能与人类思考比肩的能力，即我们通常说的 <strong>思考机器</strong>。</p><p>这种通用能力，区别于专用人工智能系统(如 人脸识别 语音识别等等深度学习应用)，更强调统一性和普遍性(多任务)，以及可解释性。</p><h2 id="主要源码地址" tabindex="-1">主要源码地址 <a class="header-anchor" href="#主要源码地址" aria-label="Permalink to &quot;主要源码地址&quot;">​</a></h2><p><a href="https://github.com/opennars/opennars" target="_blank" rel="noreferrer">https://github.com/opennars/opennars</a></p><p>亦可参考<a href="./impl/introduction">各版实现</a></p><h2 id="介绍文章" tabindex="-1">介绍文章 <a class="header-anchor" href="#介绍文章" aria-label="Permalink to &quot;介绍文章&quot;">​</a></h2><p>（英文）<a href="https://cis.temple.edu/~pwang/NARS-Intro.html" target="_blank" rel="noreferrer">https://cis.temple.edu/~pwang/NARS-Intro.html</a></p><p>亦可参考<a href="./theory/">NARS理论</a></p><h2 id="近期新闻" tabindex="-1">近期新闻 <a class="header-anchor" href="#近期新闻" aria-label="Permalink to &quot;近期新闻&quot;">​</a></h2><p>参见<a href="./news">news.md</a></p>',14)])])}const _=e(o,[["render",s]]);export{m as __pageData,_ as default};
